def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder or not postorder:
        return ""

    # Build a map of inorder traversal for O(1) access to index
    inorder_index = {val: idx for idx, val in enumerate(inorder)}

    def build(in_start, in_end, post_start, post_end):
        if in_start > in_end or post_start > post_end:
            return ""

        # The last element in the postorder is the root
        root = postorder[post_end]

        # Recursively build left and right subtrees
        root_idx = inorder_index[root]
        left_size = root_idx - in_start

        # Preorder: root, left, right
        result = root
        result += build(in_start, root_idx - 1, post_start, post_start + left_size - 1)
        result += build(root_idx + 1, in_end, post_start + left_size, post_end - 1)

        return result

    return build(0, len(inorder) - 1, 0, len(postorder) - 1)

