def hanoi_double_iterative(n: int) -> int:
    if n == 0:
        return 0
    # The recurrence relation for double-disc hanoi:
    # D(n) = 2 * D(n-1) + 2
    # With D(1) = 2
    # This gives: D(n) = 2^(n+1) - 2
    moves = 0
    for i in range(1, n + 1):
        if i == 1:
            moves = 2
        else:
            moves = 2 * moves + 2
    return moves

